# --- your code ---
class StackQueue:
    def __init__(self):
        self.inbox = []                  # newest value on top
        self.outbox = []                 # oldest value on top

    def push(self, x: int) -> None:
        self.inbox.append(x)

    def pop(self) -> int:
        self.peek()                      # make sure the oldest value is on top of outbox
        return self.outbox.pop()

    def peek(self) -> int:
        if not self.outbox:              # refill only when empty, or newer values jump ahead
            while self.inbox:
                self.outbox.append(self.inbox.pop())
        return self.outbox[-1]

    def empty(self) -> bool:
        return not self.inbox and not self.outbox


