class StackQueue:
    def __init__(self):
        self.items = []                  # one stack, newest value on top

    def push(self, x: int) -> None:
        self.items.append(x)

    def _front(self, remove: bool) -> int:
        spare = []
        while self.items:                # dig down to the oldest value...
            spare.append(self.items.pop())
        front = spare.pop() if remove else spare[-1]
        while spare:                     # ...and pile everything back every time
            self.items.append(spare.pop())
        return front

    def pop(self) -> int:
        return self._front(True)

    def peek(self) -> int:
        return self._front(False)

    def empty(self) -> bool:
        return not self.items


def run_queue(ops: list[list]) -> list:
    queue = StackQueue()
    return [getattr(queue, name)(*args) for name, *args in ops]
